"""Connects Boardwright to its engine.

The engine reads its settings from the environment when it is first
imported, so :func:`configure` must run before anything imports
``eda_agent``. Every Boardwright entry point calls it first.
"""
from __future__ import annotations

import os
from importlib import metadata

from . import paths

ENGINE_PACKAGE = "eda-agent"
ENGINE_UPSTREAM = "https://github.com/salitronic/eda-agent"


def configure() -> None:
    """Point the engine at Boardwright's folders (explicit env wins)."""
    os.environ.setdefault("EDA_AGENT_WORKSPACE", str(paths.workspace()))
    os.environ.setdefault("EDA_AGENT_SCRIPTS_DIR", str(paths.altium_scripts()))
    # The engine's web dashboard is a separate UI; Boardwright runs headless.
    os.environ.setdefault("EDA_AGENT_NO_DASHBOARD", "1")
    # Boardwright ships the engine inside its plugin and updates it with
    # the plugin; the engine must never offer or apply an upstream update.
    os.environ["EDA_AGENT_SELF_UPDATE"] = "0"
    os.environ["EDA_AGENT_UPDATE_CHECK"] = "0"


def version() -> str:
    try:
        return metadata.version(ENGINE_PACKAGE)
    except metadata.PackageNotFoundError:
        return "not installed"


def run_engine_cli(argv: list[str]) -> int:
    """Run one engine subcommand (install-scripts, relaunch, doctor ...)."""
    import sys

    configure()
    from eda_agent import server as engine_server

    saved = sys.argv
    sys.argv = ["boardwright", *argv]
    try:
        return int(engine_server.main() or 0)
    finally:
        sys.argv = saved
